fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let lines_iter = if keepends {
                s.split_inclusive(|c| c == '\n' || c == '\r')
            } else {
                // split lines without including line endings
                s.lines()
            };
            let lines: Vec<String> = lines_iter.map(|line| line.to_string()).collect();

            // Defensive: split_lines or lines always yield at least one line,
            // but if something odd happens, fallback to original string:
            if lines.is_empty() {
                vec![s]
            } else {
                lines
            }
        })
        .collect()
}